/**
 * The takeout connectors must declare where they can actually run.
 *
 * All three read an absolute path on the user's own machine. Per the SDK
 * contract (`packages/connector-sdk/src/connector-types.ts`), omitting
 * `runtime` means "runs on the server-side worker fleet (cloud)" and omitting
 * `requiredCapability` means "any worker". Declaring neither is what let
 * `worker-api/poll.ts` hand these runs to a Kubernetes pod with no ~/Downloads
 * (unpinned connections) or to the Swift Mac bridge, which cannot execute a
 * TypeScript connector at all (pinned connections) — two error strings, one
 * missing declaration.
 *
 * This is a class guard, not a per-connector one: every local-filesystem
 * takeout connector in this directory is asserted together, so adding a fourth
 * without the declaration fails here rather than in prod weeks later.
 *
 * The capability string is checked against `authorizeCapabilities` rather than
 * compared to a literal. A typo'd or non-allowlisted capability is silently
 * DROPPED at poll time, which is indistinguishable from declaring nothing —
 * the failure mode this file exists to prevent.
 */

import { beforeAll, describe, expect, mock, test } from "bun:test";
import { authorizeCapabilities } from "@lobu/core";
import { connectorSdkMock } from "./connector-sdk.mock";

mock.module("@lobu/connector-sdk", connectorSdkMock);

const CONNECTOR_MODULES = [
  "../google-takeout.connector",
  "../instagram-takeout.connector",
  "../twitter-takeout.connector",
] as const;

let definitions: Array<{ key: string; def: any }> = [];

beforeAll(async () => {
  definitions = await Promise.all(
    CONNECTOR_MODULES.map(async (mod) => {
      const { default: Connector } = await import(mod);
      const def = new Connector().definition;
      return { key: def.key as string, def };
    }),
  );
});

describe("local takeout connectors declare a device runtime", () => {
  test("all three are present (the guard is not vacuous)", () => {
    expect(definitions.map((d) => d.key).sort()).toEqual([
      "google.takeout",
      "instagram.takeout",
      "twitter.takeout",
    ]);
  });

  test("each declares os.files and a macos runtime", () => {
    for (const { key, def } of definitions) {
      expect({ key, cap: def.requiredCapability }).toEqual({
        key,
        cap: "os.files",
      });
      expect({ key, platforms: def.runtime?.platforms }).toEqual({
        key,
        platforms: ["macos"],
      });
    }
  });

  test("the declared capability survives authorizeCapabilities on macos", () => {
    for (const { key, def } of definitions) {
      const auth = authorizeCapabilities("macos", [def.requiredCapability]);
      expect({ key, authorized: auth.authorized, dropped: auth.dropped }).toEqual(
        { key, authorized: ["os.files"], dropped: [] },
      );
    }
  });

  test("a chrome-extension worker cannot serve them", () => {
    // Connection 412 is pinned to a chrome-extension worker; an extension
    // cannot read ~/Downloads. The capability must be dropped there, so the
    // device lane in poll.ts never hands it a takeout run.
    for (const { key, def } of definitions) {
      const auth = authorizeCapabilities("chrome-extension", [
        def.requiredCapability,
      ]);
      expect({ key, authorized: auth.authorized }).toEqual({
        key,
        authorized: [],
      });
    }
  });
});

