test("handleFromUserLink returns null for the /intent/user form the archive ACTUALLY emits", () => {
  // Every userLink in a real follower.js/following.js looks like this — the
  // archive carries no handle for a follow at all. Reading the first path
  // segment named all 824 prod follower entities "intent" and stamped
  // `x_handle: "intent"` on each; since x_handle is an identity namespace, a
  // real @intent account would then fuse into that one junk entity.
  expect(
    handleFromUserLink(
      "https://twitter.com/intent/user?user_id=1703117072769683456"
    )
  ).toBe(null);
  // The reserved word is rejected by the normalizer too, so it cannot arrive
  // from any other path (restated metadata, hand-written config).
  expect(normalizeXHandle("intent")).toBe(null);
  expect(normalizeXHandle("@Intent")).toBe(null);
  // Other non-profile segments that would mass-merge the same way.
  expect(handleFromUserLink("https://x.com/i/lists/123")).toBe(null);
  expect(handleFromUserLink("https://twitter.com/home")).toBe(null);
  expect(handleFromUserLink("https://twitter.com/search?q=x")).toBe(null);
});

test("handleFromUserLink recovers the normalized handle from a profile link", () => {
  // Pins the fix as targeted — rejecting everything would satisfy the
  // reserved-word assertions above while disabling handle recovery entirely.
  expect(handleFromUserLink("https://twitter.com/Jack")).toBe("jack");
  expect(handleFromUserLink("https://x.com/elonmusk?ref=1")).toBe("elonmusk");
  expect(handleFromUserLink("not-a-link")).toBe(null);
