  expect(resolvePath(row, "metadata.username")).toBe("rampue");
  // profile_url still carries the link, so nothing is lost.
  expect(resolvePath(row, "metadata.profile_url")).toBe(
    "https://www.instagram.com/_u/rampue"
  );
});

