  /**
   * Saved places, starred lists, and reviews.
   *
   * Three sources with different shapes and different date behaviour:
   *
   * - `Maps (your places)/Saved Places.json` — GeoJSON, one feature per saved
   *   pin, carrying its own save `date`.
   * - `Maps (your places)/Reviews.json` — same envelope plus a star rating and
   *   the answered prompts ("Trip type: Vacation").
   * - `Saved/<list>.csv` — the user's lists ("Favorite places", "Want to go").
   *   The list NAME is only in the filename, and rows carry NO date at all, so
   *   the file's mtime stands in. That is deliberate rather than a constant:
   *   `takeBatch` filters on `occurred_at` against the checkpoint, so a fixed
   *   sentinel would make every later edit to a list invisible forever, while
   *   mtime advances when the list actually changes and lets the row re-emit.
   */
  private readMapsEvents(takeoutDir: string): EventEnvelope[] {
    return [
      ...this.readMapsPlaceFile(takeoutDir, "Saved Places.json", "saved_place"),
      ...this.readMapsPlaceFile(takeoutDir, "Reviews.json", "place_review"),
      ...this.readMapsListEvents(takeoutDir),
    ];
  }

  /** One GeoJSON file under `Maps (your places)`. */
  private readMapsPlaceFile(
    takeoutDir: string,
    fileName: string,
    originType: "saved_place" | "place_review"
  ): EventEnvelope[] {
    const filePath = path.join(takeoutDir, "Maps (your places)", fileName);
    if (!existsSync(filePath)) return [];
    const parsed = readJsonFile<{ features?: MapsFeature[] }>(filePath);
    const features = parsed?.features;
    if (!Array.isArray(features)) return [];

    return features.flatMap((feature) => {
      const props = feature.properties;
      const name = props?.location?.name?.trim();
      // No name means no usable place — a bare coordinate is not worth an event.
      if (!name) return [];
      const occurredAt = parseDate(props?.date);
      if (!occurredAt) return [];

      const address = props?.location?.address?.trim();
      const rating = props?.five_star_rating_published;
      const answers = (props?.questions ?? [])
        .map((q) => (q.question && q.selected_option ? `${q.question}: ${q.selected_option}` : ""))
        .filter(Boolean);
      // Coordinates are GeoJSON order — [longitude, latitude], NOT lat/lng.
      const [longitude, latitude] = feature.geometry?.coordinates ?? [];

      return [
        {
          origin_id: stableId("google_maps_place", [
            originType,
            props?.google_maps_url,
            name,
          ]),
          origin_type: originType,
          occurred_at: occurredAt,
          title: name,
          payload_text: [
            originType === "place_review"
              ? `Reviewed ${name}${rating ? ` — ${rating}/5` : ""}`
              : `Saved ${name}`,
            address,
            ...answers,
          ]
            .filter(Boolean)
            .join("\n"),
          source_url: props?.google_maps_url,
          metadata: {
            platform: "google_maps",
            place_name: name,
            address,
            country_code: props?.location?.country_code,
            latitude,
            longitude,
            ...(rating === undefined ? {} : { rating }),
          },
        },
      ];
    });
  }

  /** The `Saved/` CSV lists — "Favorite places", "Want to go", and friends. */
  private readMapsListEvents(takeoutDir: string): EventEnvelope[] {
    const savedDir = path.join(takeoutDir, "Saved");
    if (!existsSync(savedDir)) return [];

    return readdirSync(savedDir)
      .filter((file) => file.endsWith(".csv"))
      .flatMap((file) => {
        const filePath = path.join(savedDir, file);
        const listName = path.basename(file, ".csv");
        const occurredAt = parseDateOrUndefined(
          statSync(filePath).mtime.toISOString()
        );
        if (!occurredAt) return [];

        return parseCsv(readFileSync(filePath, "utf8")).flatMap((row) => {
          const title = row.Title?.trim();
          // Google emits a trailing all-empty row in every list file.
          if (!title) return [];
          const note = row.Note?.trim();
          const comment = row.Comment?.trim();

          return [
            {
              origin_id: stableId("google_maps_list_place", [
                listName,
                title,
                row.URL,
              ]),
              origin_type: "saved_list_place",
              occurred_at: occurredAt,
              title,
              payload_text: [`${listName}: ${title}`, note, comment]
                .filter(Boolean)
                .join("\n"),
              source_url: row.URL || undefined,
              metadata: {
                platform: "google_maps",
                place_name: title,
                list: listName,
                note: note || undefined,
                tags: row.Tags || undefined,
              },
            },
          ];
        });
      });
  }
}

