import { afterEach, beforeEach, expect, test } from "bun:test";
import { mkdtemp, rm, writeFile, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

let dir: string;
let file: string;

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "late-assert-"));
  file = join(dir, "store.json");
  console.log(`[beforeEach] dir=${dir.slice(-12)}`);
});

afterEach(async () => {
  console.log(`[afterEach ] rm  ${dir.slice(-12)}`);
  await rm(dir, { recursive: true, force: true });
});

test("slow test writes, then asserts after exceeding its timeout", async () => {
  const myDir = dir.slice(-12);
  await writeFile(file, JSON.stringify({ contexts: { a: 1 } }));
  console.log(`[slow test ] wrote into ${myDir}`);

  // Exceed the 100ms timeout below.
  await new Promise((r) => setTimeout(r, 400));

  // Late assertion: reads the MODULE-SCOPED `file`, which by now may point at
  // a different test's directory.
  console.log(`[slow test ] late read from ${dir.slice(-12)} (started in ${myDir})`);
  const raw = await readFile(file, "utf8").catch(() => "<<MISSING>>");
  const parsed = raw === "<<MISSING>>" ? { contexts: {} } : JSON.parse(raw);
  console.log(`[slow test ] contexts=${Object.keys(parsed.contexts).length}`);
  expect(Object.keys(parsed.contexts).length).toBeGreaterThan(0);
}, 100);

test("a following fast test", async () => {
  await writeFile(file, JSON.stringify({ contexts: {} }));
  expect(true).toBe(true);
});

